import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

custom_conv2d_cpp_source = r"""
torch::Tensor custom_conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dil_h,
    int dil_w
);
"""

custom_conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void custom_conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N,
    const int C,
    const int H,
    const int W,
    const int OC,
    const int kernel_h,
    const int kernel_w,
    const int stride_h,
    const int stride_w,
    const int pad_h,
    const int pad_w,
    const int dil_h,
    const int dil_w,
    const bool has_bias,
    const int OH,
    const int OW
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elems = N * OC * OH * OW;
    if (idx < total_elems) {
        int ow = idx % OW;
        int oh = (idx / OW) % OH;
        int oc = (idx / (OH * OW)) % OC;
        int n  = idx / (OC * OH * OW);

        float val = 0.0f;
        // Compute convolution
        for (int c = 0; c < C; c++) {
            for (int kh = 0; kh < kernel_h; kh++) {
                for (int kw = 0; kw < kernel_w; kw++) {
                    int ih = oh * stride_h + kh * dil_h - pad_h;
                    int iw = ow * stride_w + kw * dil_w - pad_w;
                    if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                        float inp_val = input[((n * C + c) * H + ih) * W + iw];
                        float wgt_val = weight[(((oc * C) + c) * kernel_h + kh) * kernel_w + kw];
                        val += inp_val * wgt_val;
                    }
                }
            }
        }
        // Add bias if present
        if (has_bias) {
            val += bias[oc];
        }
        output[((n * OC + oc) * OH + oh) * OW + ow] = val;
    }
}

torch::Tensor custom_conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dil_h,
    int dil_w
) {
    // Ensure input is float tensor on CUDA
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda() || bias.numel() == 0, "Bias must be a CUDA tensor or empty");
    TORCH_CHECK(input.dim() == 4, "Input must be 4D (N, C, H, W)");
    TORCH_CHECK(weight.dim() == 4, "Weight must be 4D (OC, C, kH, kW)");

    const auto N = input.size(0);
    const auto C = input.size(1);
    const auto H = input.size(2);
    const auto W = input.size(3);

    const auto OC = weight.size(0);
    const auto kernel_h = weight.size(2);
    const auto kernel_w = weight.size(3);

    // Compute output dimensions (following PyTorch's formula)
    const int OH = (int) ((H + 2 * pad_h - dil_h * (kernel_h - 1) - 1) / stride_h + 1);
    const int OW = (int) ((W + 2 * pad_w - dil_w * (kernel_w - 1) - 1) / stride_w + 1);

    TORCH_CHECK(OH > 0 && OW > 0, "Output size is non-positive, check kernel/padding/stride/dilation settings.");

    // Create output tensor
    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({N, OC, OH, OW}, options);

    bool has_bias = (bias.numel() == OC);

    // Launch CUDA kernel
    int total_elems = N * OC * OH * OW;
    const int threads = 256;
    const int blocks = (total_elems + threads - 1) / threads;

    custom_conv2d_forward_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N,
        C,
        H,
        W,
        OC,
        kernel_h,
        kernel_w,
        stride_h,
        stride_w,
        pad_h,
        pad_w,
        dil_h,
        dil_w,
        has_bias,
        OH,
        OW
    );
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("custom_conv2d_forward", &custom_conv2d_forward, "Custom Conv2D forward");
}
"""

# Build the extension
custom_conv2d = load_inline(
    name="custom_conv2d",
    cpp_sources=custom_conv2d_cpp_source,
    cuda_sources=custom_conv2d_source,
    functions=["custom_conv2d_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: int = 1,
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.use_bias = bias

        # Register parameters (weight and optional bias) similarly to Conv2d
        kh, kw = kernel_size
        # Follows PyTorch init style (simplified)
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kh, kw))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
            fan_in = in_channels * kh * kw
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.bias = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Handle strides
        if isinstance(self.stride, int):
            stride_h, stride_w = self.stride, self.stride
        else:
            stride_h, stride_w = self.stride

        # Call our custom conv2d kernel
        b = torch.zeros(0, device=x.device, dtype=x.dtype)
        if self.bias is not None:
            b = self.bias
        return custom_conv2d.custom_conv2d_forward(
            x, 
            self.weight, 
            b,
            stride_h,
            stride_w,
            self.padding[0],
            self.padding[1],
            self.dilation[0],
            self.dilation[1]
        )
